  /// The merged look of an allowed combination; none when the contract does not allow it.
  public func appearance(variant: ButtonVariant, size: ButtonSize, state: ButtonState) -> ButtonAppearance? {
    looks.first { $0.variant == variant && $0.size == size && $0.state == state }?.appearance
  }
}

/// One `AppButton` gallery cell and its test ID.
nonisolated public struct ButtonGalleryEntry: Sendable, Equatable {
  public let variant: ButtonVariant
  public let size: ButtonSize
  public let state: ButtonState
  public let testId: String
}

